import * as THREE from 'three';
// Hair geometry is generated by JS: fitted scalp, curved locks, and three-strand braids.
export const hairDefaults={frontHair:'parted',backHair:'short',sideHair:'short',braid:'none',frontLength:50,backLength:50,sideLength:50,braidLength:50,hairVolume:50};
export const hairChoices={frontHair:[['none','无前发'],['straight','齐刘海'],['parted','中分'],['swept','侧分']],backHair:[['none','无后发'],['short','短后发'],['bob','齐颈后发'],['long','长后发']],sideHair:[['none','无侧发'],['short','短鬓发'],['long','长侧发']],braid:[['none','无发辫'],['single','后发辫'],['double','双发辫']]};
export const hairRanges={frontLength:['前发长度','短','长'],backLength:['后发长度','短','长'],sideLength:['侧发长度','短','长'],braidLength:['发辫长度','短','长'],hairVolume:['蓬松度','贴合','蓬松']};
const skullCache=new WeakMap();
const v=(x,y,z)=>new THREE.Vector3(x,y,z);
function skull(base){
 if(skullCache.has(base))return skullCache.get(base);
 const eye=(base.landmarks.leftEye[1]+base.landmarks.rightEye[1])/2;
 const center=v(0,eye+.042,base.landmarks.head[2]);
 const positions=[],indices=[];
 for(const mesh of base.meshes){
  const offset=positions.length/3;positions.push(...mesh.positions.map(x=>x/100000));
  for(const part of mesh.groups){if(!base.materials[part.material].name.includes('_SKIN'))continue;
   for(let i=0;i<part.indices.length;i+=3){const ids=part.indices.slice(i,i+3);if(ids.every(id=>mesh.positions[id*3+1]/100000>eye-.15))indices.push(...ids.map(id=>id+offset));}
  }
 }
 const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));geo.setIndex(indices);geo.computeBoundingSphere();
 const material=new THREE.MeshBasicMaterial({side:THREE.DoubleSide});
 const surface=new THREE.Mesh(geo,material);surface.updateMatrixWorld();
 const ray=new THREE.Raycaster();const cache=new Map();
 function sample(theta,azimuth){
  const key=theta.toFixed(5)+':'+azimuth.toFixed(5);if(cache.has(key))return cache.get(key).clone();
  const direction=v(Math.sin(theta)*Math.sin(azimuth),Math.cos(theta),Math.sin(theta)*Math.cos(azimuth));
  ray.set(center,direction);ray.far=.30;
  const hits=ray.intersectObject(surface,false);
  const radius=hits[0]?.distance ?? 1/Math.sqrt((direction.x/.10)**2+(direction.y/.11)**2+(direction.z/.11)**2);
  const point=center.clone().addScaledVector(direction,radius+.005);cache.set(key,point);return point.clone();
 }
 const result={center,eye,sample};skullCache.set(base,result);return result;
}
function geometry(points,indices){const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(points,3));g.setIndex(indices);g.computeVertexNormals();return g;}
function lock(points,width,depth,outward){
 const curve=new THREE.CatmullRomCurve3(points);const p=[],idx=[],rows=18,cols=6;
 for(let i=0;i<=rows;i++){
  const t=i/rows,center=curve.getPoint(t),tangent=curve.getTangent(t);
  const side=new THREE.Vector3().crossVectors(tangent,outward).normalize();
  if(side.lengthSq()<.01)side.set(1,0,0);
  const taper=t>.75?Math.max(.04,(1-t)/.25):1;
  for(let j=0;j<=cols;j++){
   const u=2*j/cols-1;const q=center.clone().addScaledVector(side,u*width*.5*taper).addScaledVector(outward,depth*Math.sqrt(Math.max(0,1-u*u))*taper);
   p.push(q.x,q.y,q.z);
   if(i<rows&&j<cols){const a=i*(cols+1)+j,b=a+cols+1;idx.push(a,b,a+1,a+1,b,b+1);}
  }
 }
 return geometry(p,idx);
}
export function createHair(base,input,deform,material){
 const state={...hairDefaults,...input};for(const key of Object.keys(hairRanges))state[key]=Number.isFinite(state[key])?Math.max(0,Math.min(100,state[key])):50;
 const {sample,eye,center}=skull(base),group=new THREE.Group();group.name='ProceduralHair';
 const volume=.002+state.hairVolume*.00010;
 function add(g,name){
  const p=g.attributes.position;for(let i=0;i<p.count;i++){const q=deform(p.getX(i),p.getY(i),p.getZ(i),'ProceduralHair');p.setXYZ(i,...q);}p.needsUpdate=true;g.computeVertexNormals();g.computeBoundingSphere();
  const mesh=new THREE.Mesh(g,material);mesh.name=name;mesh.userData.part=name;mesh.castShadow=false;group.add(mesh);
 }
 const bald=state.frontHair==='none'&&state.backHair==='none'&&state.sideHair==='none'&&state.braid==='none';if(bald)return group;
 // The scalp is ray-fitted to the actual CC0 skull, keeping the forehead and ears clear.
 const p=[],idx=[],rows=14,cols=48;
 for(let i=0;i<=rows;i++)for(let j=0;j<=cols;j++){
  const a=j/cols*Math.PI*2,front=(Math.cos(a)+1)/2;
  const max=2.35-.92*Math.pow(front,3),theta=.018+(max-.018)*i/rows;
  const point=sample(theta,a),normal=point.clone().sub(center).normalize();point.addScaledVector(normal,volume);p.push(...point.toArray());
  if(i<rows&&j<cols){const q=i*(cols+1)+j,n=q+cols+1;idx.push(q,q+1,n,q+1,n+1,n);}
 }
 add(geometry(p,idx),'HairScalp');
 if(state.frontHair!=='none')for(let i=0;i<9;i++){
  const f=(i-4)/4,a=f*.80,start=sample(.38,a),mid=sample(.93,a),end=sample(1.40,a);
  start.addScaledVector(start.clone().sub(center).normalize(),volume+.001);mid.z+=volume+.008;
  let length=eye+.040-state.frontLength*.00048;
  if(state.frontHair==='parted'){length+=.035*(1-Math.abs(f));end.x+=Math.sign(f||1)*.018;}
  if(state.frontHair==='swept'){end.x+=.035;length+=.035*(1-(f+1)/2);}
  end.y=length+.004*Math.sin(i*2.4);end.z+=volume+.010;
  add(lock([start,mid,end],.026,.004,v(Math.sin(a)*.35,0,1).normalize()),'HairFront');
 }
 if(state.backHair!=='none'){
  const drop=state.backHair==='short'?.055+state.backLength*.00055:state.backHair==='bob'?.14+state.backLength*.00075:.25+state.backLength*.0024;
  for(let i=0;i<19;i++){
   const a=.94+i/18*(Math.PI*2-1.88),out=v(Math.sin(a),0,Math.cos(a)),start=sample(.40,a),mid=sample(1.50,a),root=sample(1.95,a);
   for(const q of [start,mid,root])q.addScaledVector(out,volume+.004);
   const end=root.clone();end.y=eye-drop+.012*Math.sin(i*2.7);
   // Long locks remain outside the back and shoulders rather than falling through the shirt.
   const clearance=.12+Math.max(0,eye-.13-end.y)*.17;
   end.x=Math.sin(a)*Math.max(Math.abs(root.x),clearance);end.z=center.z+Math.cos(a)*Math.max(.12,clearance);
   add(lock([start,mid,root,end],.033,.004,out),'HairBack');
  }
 }
 if(state.sideHair!=='none')for(const sign of [-1,1])for(let i=0;i<3;i++){
  const a=sign*(1.23+i*.18),out=v(sign,0,.15).normalize(),start=sample(.60,a),mid=sample(1.45,a),end=sample(1.85,a);
  mid.addScaledVector(out,volume+.005);end.addScaledVector(out,volume+.012);
  const drop=state.sideHair==='short'?.035+state.sideLength*.0007:.10+state.sideLength*.0021;
  end.y=eye-drop+.010*i;end.x=sign*Math.max(Math.abs(end.x),.112+Math.max(0,drop-.12)*.30);end.z+=.007;
  add(lock([start,mid,end],.023,.0035,out),'HairSide');
 }
 if(state.braid!=='none'){
  const anchors=state.braid==='double'?[-1,1]:[0];
  for(const sign of anchors){
   const anchor=sample(1.8,sign===0?Math.PI:sign*2.05);anchor.y=eye-.06;
   anchor.x=sign*.125;anchor.z=sign===0?center.z-.145:center.z-.055;
   const angle=sign===0?Math.PI:sign*2.05;
   const outward=v(sign*.45,0,-1).normalize();
   const gatherStart=sample(1.35,angle),gatherMid=sample(2.05,angle);
   gatherStart.addScaledVector(outward,volume);gatherMid.addScaledVector(outward,volume+.006);
   add(lock([gatherStart,gatherMid,anchor],.044,.005,outward),'HairBraidRoot');
   const length=.14+state.braidLength*.0032;
   for(let strand=0;strand<3;strand++){
    const points=[];
    for(let i=0;i<=64;i++){
     const t=i/64,phase=t*Math.PI*2*(3+length*9)+strand*Math.PI*2/3,r=.012*(1-.65*t);
     const x=anchor.x+sign*.065*t+r*Math.cos(phase),y=anchor.y-length*t;
     const z=anchor.z-.05*t+r*Math.sin(phase);points.push(v(x,y,z));
    }
    const curve=new THREE.CatmullRomCurve3(points);
    const g=new THREE.TubeGeometry(curve,64,.0075,6,false);
    add(g,'HairBraid');
   }
  }
 }
 return group;
}
